//! Exact structural corrections after generic prefix swaps in ascending order 1..15.
//! Constants are derived from B_i=A_j, not input sampling. All helpers are dirty and restored.
use super::{builder::B, mask};
use crate::circuit::QubitId;

pub(crate) type Word = [u64; 4];
fn bit(x: Word, j: usize) -> bool { ((x[j/64] >> (j%64)) & 1) != 0 }

/// Controlled exact transposition of two n-bit constants, fixing every other state.
/// Affine conjugation maps endpoints to 0 and 2^pivot; one negative-control MCX swaps them.
pub(crate) fn controlled_const_swap(b: &mut B, z: &[QubitId], left: Word, right: Word,
                                   control: QubitId, dirty: &[QubitId]) {
    assert!(z.len() <= 256);
    let Some(pivot) = (0..z.len()).find(|&j| bit(left,j) != bit(right,j)) else { return; };
    for (j,&q) in z.iter().enumerate() { if bit(left,j) { b.x(q); } }
    for (j,&q) in z.iter().enumerate() { if j != pivot && bit(left,j) != bit(right,j) { b.cx(z[pivot],q); } }
    let mut controls = vec![control];
    for (j,&q) in z.iter().enumerate() { if j != pivot { b.x(q); controls.push(q); } }
    mask::mcx_dirty(b, &controls, z[pivot], dirty);
    for (j,&q) in z.iter().enumerate() { if j != pivot { b.x(q); } }
    for (j,&q) in z.iter().enumerate().rev() { if j != pivot && bit(left,j) != bit(right,j) { b.cx(z[pivot],q); } }
    for (j,&q) in z.iter().enumerate() { if bit(left,j) { b.x(q); } }
}
fn xor_eq_const(b: &mut B, a: &[QubitId], value: Word, target: QubitId, dirty: &[QubitId]) {
    for (j,&q) in a.iter().enumerate() { if !bit(value,j) { b.x(q); } }
    mask::mcx_dirty(b,a,target,dirty);
    for (j,&q) in a.iter().enumerate() { if !bit(value,j) { b.x(q); } }
}
/// a has 255 bits, z has 256, ylow has 252. No allocation, no clean flag, no phase gates.
/// Each (source, left, right) tuple controls one exact transposition by [a=source].
pub fn correct_seed_exceptions(b: &mut B, z: &[QubitId], a: &[QubitId], ylow: &[QubitId]) {
    assert_eq!(z.len(),256); assert_eq!(a.len(),255); assert!(ylow.len()>=252);
    let g = ylow[0];
    let mut pred_dirty = ylow[1..252].to_vec(); pred_dirty.extend([z[0],z[1]]);
    for &(source,left,right) in CORRECTIONS {
        // The complete controlled transposition is an involution for either g.
        // Echo of the unchanged source predicate cancels the arbitrary initial g.
        xor_eq_const(b,a,source,g,&pred_dirty);
        controlled_const_swap(b,z,left,right,g,a);
        xor_eq_const(b,a,source,g,&pred_dirty);
        controlled_const_swap(b,z,left,right,g,a);
    }
}
